output_text:
[
  {
    "id": "no_carts_single_file",
    "text": "Shopping carts are prohibited in single-file shelf aisles where the horizontal clearance is only one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_narrow_with_cart",
    "text": "An agent must not enter a single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_cart_only_in_bays",
    "text": "If a shopper lets go of a cart, they must do so only in a wide cart-parking bay rather than in an aisle.",
    "abstraction": {
      "state_properties": {
        "wideJunction": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                6
              ]
            }
          ]
        },
        "cartParkingBay": {
          "and": [
            "wideJunction",
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartReleased": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartReleased",
          {
            "not": "cartParkingBay"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart to go into a pedestrian-only aisle, the shopper is obliged to retrieve a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartReleased": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRetrieved": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartReleased",
      "discharge": "cartRetrieved"
    }
  },
  {
    "id": "cartless_only_in_allowed_zones",
    "text": "Except for the entrance/cart-pickup area, a shopper without a cart may move only inside the hand-carry pedestrian aisle or its parking bay.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideCartBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "cartPickupArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartlessMovementZone": {
          "or": [
            "singleFileShelfAisle",
            "wideCartBay",
            "cartPickupArea"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          {
            "not": "cartlessMovementZone"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_service_in_single_file",
    "text": "Items on shelves in a single-file aisle must be serviced by hand rather than while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileServicePoint": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileServicePoint"
        ]
      }
    }
  },
  {
    "id": "do_not_abandon_cart_by_shelves",
    "text": "A cart may not be abandoned directly next to shelving, to avoid blocking access to shelf faces.",
    "abstraction": {
      "state_properties": {
        "besideShelf": "adjShelf"
      },
      "events": {
        "cartReleased": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartReleased",
          "besideShelf"
        ]
      }
    }
  },
  {
    "id": "eastbound_public_aisles",
    "text": "Wide public shopping aisles operate one-way eastbound, so westward travel through them is prohibited.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalPublicAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "wideHorizontalPublicAisle"
        ]
      }
    }
  }
]
